Implementing a red-black tree in Rust is a complex task that involves careful management of tree nodes and their properties. Below is a basic implementation of a red-black tree in Rust. This implementation includes insertion and some helper functions to maintain the red-black properties.

```rust
use std::cmp::Ordering;
use std::ptr::null_mut;

#[derive(Clone, Copy, PartialEq)]
enum Color {
    Red,
    Black,
}

struct Node<K, V> {
    key: K,
    value: V,
    color: Color,
    left: *mut Node<K, V>,
    right: *mut Node<K, V>,
    parent: *mut Node<K, V>,
}

impl<K, V> Node<K, V> {
    fn new(key: K, value: V, color: Color) -> *mut Self {
        Box::into_raw(Box::new(Node {
            key,
            value,
            color,
            left: null_mut(),
            right: null_mut(),
            parent: null_mut(),
        }))
    }
}

struct RedBlackTree<K, V> {
    root: *mut Node<K, V>,
}

impl<K, V> RedBlackTree<K, V>
where
    K: Ord,
{
    fn new() -> Self {
        RedBlackTree { root: null_mut() }
    }

    fn insert(&mut self, key: K, value: V) {
        let mut node = Node::new(key, value, Color::Red);
        let mut parent = null_mut();
        let mut current = self.root;

        while !current.is_null() {
            parent = current;
            unsafe {
                if (*node).key < (*current).key {
                    current = (*current).left;
                } else {
                    current = (*current).right;
                }
            }
        }

        unsafe {
            (*node).parent = parent;
        }

        if parent.is_null() {
            self.root = node;
        } else {
            unsafe {
                if (*node).key < (*parent).key {
                    (*parent).left = node;
                } else {
                    (*parent).right = node;
                }
            }
        }

        self.insert_fixup(node);
    }

    fn insert_fixup(&mut self, mut node: *mut Node<K, V>) {
        unsafe {
            while !(*node).parent.is_null() && (*(*node).parent).color == Color::Red {
                if (*node).parent == (*(*(*node).parent).parent).left {
                    let uncle = (*(*(*node).parent).parent).right;
                    if !uncle.is_null() && (*uncle).color == Color::Red {
                        (*(*node).parent).color = Color::Black;
                        (*uncle).color = Color::Black;
                        (*(*(*node).parent).parent).color = Color::Red;
                        node = (*(*node).parent).parent;
                    } else {
                        if node == (*(*node).parent).right {
                            node = (*node).parent;
                            self.left_rotate(node);
                        }
                        (*(*node).parent).color = Color::Black;
                        (*(*(*node).parent).parent).color = Color::Red;
                        self.right_rotate((*(*node).parent).parent);
                    }
                } else {
                    let uncle = (*(*(*node).parent).parent).left;
                    if !uncle.is_null() && (*uncle).color == Color::Red {
                        (*(*node).parent).color = Color::Black;
                        (*uncle).color = Color::Black;
                        (*(*(*node).parent).parent).color = Color::Red;
                        node = (*(*node).parent).parent;
                    } else {
                        if node == (*(*node).parent).left {
                            node = (*node).parent;
                            self.right_rotate(node);
                        }
                        (*(*node).parent).color = Color::Black;
                        (*(*(*node).parent).parent).color = Color::Red;
                        self.left_rotate((*(*node).parent).parent);
                    }
                }
            }
            (*self.root).color = Color::Black;
        }
    }

    fn left_rotate(&mut self, node: *mut Node<K, V>) {
        unsafe {
            let right_child = (*node).right;
            (*node).right = (*right_child).left;

            if !(*right_child).left.is_null() {
                (*(*right_child).left).parent = node;
            }

            (*right_child).parent = (*node).parent;

            if (*node).parent.is_null() {
                self.root = right_child;
            } else if node == (*(*node).parent).left {
                (*(*node).parent).left = right_child;
            } else {
                (*(*node).parent).right = right_child;
            }

            (*right_child).left = node;
            (*node).parent = right_child;
        }
    }

    fn right_rotate(&mut self, node: *mut Node<K, V>) {
        unsafe {
            let left_child = (*node).left;
            (*node).left = (*left_child).right;

            if !(*left_child).right.is_null() {
                (*(*left_child).right).parent = node;
            }

            (*left_child).parent = (*node).parent;

            if (*node).parent.is_null() {
                self.root = left_child;
            } else if node == (*(*node).parent).right {
                (*(*node).parent).right = left_child;
            } else {
                (*(*node).parent).left = left_child;
            }

            (*left_child).right = node;
            (*node).parent = left_child;
        }
    }
}

fn main() {
    let mut tree = RedBlackTree::new();
    tree.insert(10, "value10");
    tree.insert(20, "value20");
    tree.insert(30, "value30");
    tree.insert(15, "value15");
    tree.insert(25, "value25");

    // The tree is now a red-black tree with the inserted values.
}
```

### Explanation:
- **Node Structure**: Each node contains a key, value, color, and pointers to its left and right children and parent.
- **RedBlackTree Structure**: The tree itself contains a pointer to the root node.
- **Insertion**: The `insert` function adds a new node to the tree and then calls `insert_fixup` to restore the red-black properties.
- **Insert Fixup**: The `insert_fixup` function ensures that the tree maintains its properties after insertion by performing rotations and recoloring nodes as necessary.
- **Rotations**: The `left_rotate` and `right_rotate` functions are used to balance the tree.

### Safety Considerations:
- The implementation uses raw pointers (`*mut Node<K, V>`) to manage tree nodes, which requires careful handling to avoid undefined behavior. In a production environment, you might want to use safer abstractions like `Rc` and `RefCell` or `Box` with proper lifetimes.
- The `unsafe` blocks are necessary because Rust cannot guarantee the safety of dereferencing raw pointers.

